CREATE COLUMN TABLE "TEST_AP"."OLLF" ("AbsEntry" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(100) NOT NULL , "Descr" NVARCHAR(250), "MenuGuid" NVARCHAR(32), "Version" NVARCHAR(5), "SchVersion" NVARCHAR(5), "OutPath" NCLOB MEMORY THRESHOLD 1000, "FrmId" INTEGER CS_INT, "UpdateNum" INTEGER CS_INT DEFAULT 0, "MenuName" NVARCHAR(100), "MenuPath" NVARCHAR(250), "Assigned" NVARCHAR(10) DEFAULT 'N', "SboVersion" NVARCHAR(13), "Type" NVARCHAR(5) DEFAULT 'L', "SubType" NVARCHAR(6), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OLLF_NAME" ON "TEST_AP"."OLLF" ( "Name" ASC )